p = pathlib.Path("calc/expr.py")
s = p.read_text()

# 1. docstring grammar
s = s.replace(
"""    term    := unary (('*' | '/') unary)*
    unary   := '-' unary | power
    power   := primary ('^' unary)?          # right-associative; exponent may be signed
    primary := NUMBER | IDENT | '(' expr ')'
""",
"""    term    := unary (('*' | '/' | '%') unary)*
    unary   := '-' unary | power
    power   := primary ('^' unary)?          # right-associative; exponent may be signed
    primary := NUMBER | IDENT | IDENT '(' [expr (',' expr)*] ')' | '(' expr ')'
""")

# 2. imports
s = s.replace("import re\nfrom typing import Iterator, NamedTuple\n",
              "import math\nimport re\nfrom typing import Callable, Iterator, NamedTuple\n")

# 3. tokenizer: add % and ,
s = s.replace(r"  | (?P<op>[-+*/^()])", r"  | (?P<op>[-+*/%^(),])")

# 4. function table, inserted before class _Parser
funcs = '''
def _sqrt(x: float) -> float:
    if x < 0:
        raise ExprError(f"sqrt of negative number {x}")
    return math.sqrt(x)


# name -> (implementation, min_args, max_args or None for unbounded)
_FUNCTIONS: dict[str, tuple[Callable[..., float], int, int | None]] = {
    "min": (min, 1, None),
    "max": (max, 1, None),
    "sqrt": (_sqrt, 1, 1),
    "abs": (abs, 1, 1),
}


class _Parser:'''
s = s.replace("\nclass _Parser:", funcs, 1)

# 5. term rule: add modulo
s = s.replace(
'''        while (op := self._accept_op("*", "/")) is not None:
            pos = self._cur.pos
            rhs = self._unary()
            if op == "*":
                value *= rhs
            else:
                if rhs == 0:
                    raise ExprError(f"division by zero at position {pos}")
                value /= rhs
        return value''',
'''        while (op := self._accept_op("*", "/", "%")) is not None:
            pos = self._cur.pos
            rhs = self._unary()
            if op == "*":
                value *= rhs
            elif op == "/":
                if rhs == 0:
                    raise ExprError(f"division by zero at position {pos}")
                value /= rhs
            else:
                if rhs == 0:
                    raise ExprError(f"modulo by zero at position {pos}")
                value %= rhs
        return value''')

# 6. primary: function calls
s = s.replace(
'''        if tok.kind == "ident":
            self._advance()
            try:
                return float(self._vars[tok.value])
            except KeyError:
                raise ExprError(f"unknown variable {tok.value!r}") from None
''',
'''        if tok.kind == "ident":
            self._advance()
            if self._accept_op("(") is not None:
                return self._call(tok.value, self._args())
            try:
                return float(self._vars[tok.value])
            except KeyError:
                raise ExprError(f"unknown variable {tok.value!r}") from None
''')

# 7. helper methods for calls, appended after _primary (before evaluate)
helpers = '''
    def _args(self) -> list[float]:
        """Parse a comma-separated argument list; the '(' is already consumed."""
        args: list[float] = []
        if self._accept_op(")") is not None:
            return args
        args.append(self._expr())
        while self._accept_op(",") is not None:
            args.append(self._expr())
        self._expect_op(")")
        return args

    @staticmethod
    def _call(name: str, args: list[float]) -> float:
        try:
            func, lo, hi = _FUNCTIONS[name]
        except KeyError:
            raise ExprError(f"unknown function {name!r}") from None
        n = len(args)
        if n < lo or (hi is not None and n > hi):
            if hi is None:
                want = f"at least {lo}"
            elif lo == hi:
                want = str(lo)
            else:
                want = f"between {lo} and {hi}"
            raise ExprError(f"{name}() takes {want} argument(s), got {n}")
        return float(func(*args))


def evaluate('''
s = s.replace("\n\ndef evaluate(", helpers, 1)
p.write_text(s)
